WITH flattened AS (SELECT id, plan, effective_from, currency, val FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) e AS val) SELECT currency, DATE_TRUNC('YEAR', effective_from) AS year_start, CASE WHEN val >= 67 THEN 'PREMIUM' ELSE 'STANDARD' END AS val_tier, SUM(val) AS total_val, APPROX_PERCENTILE(val, ARRAY(0.25, 0.5, 0.75)) AS val_quartiles, COUNT(CASE WHEN currency = 'EUR' THEN 1 END) AS eur_count, COUNT(*) AS cnt, SUM(CASE WHEN currency = 'USD' THEN val ELSE 0 END) AS usd_val, SUM(CASE WHEN plan = 'pro' THEN val ELSE 0 END) AS pro_val FROM flattened GROUP BY 1, 2, 3 HAVING COUNT(*) < 1;
